class DataStructure<T> {
    private class Node<1*> { // EXCEPT THIS LINE
        public T data;
        public Node next, prev;

        public Node(T data) { // EXCEPT THIS LINE
            this.data = data;
        }
    }

    private Node head, tail;
    private int size;

    public DataStructure() {
        head = tail = null;
        size = 0;
    }

    public void addFront(T data) {
        Node newNode = new Node(data);
        if (head == null) {
            tail = newNode;
        } else {
            newNode.next = head;
            head.prev = newNode;
        }
        head = newNode;
        size++;
    }

    public void addBack(T data) {
        Node newNode = new Node(data);
        if (tail == null) {
            head = newNode;
        } else {
            newNode.prev = tail;
            tail.next = newNode;
        }
        tail = newNode;
        size++;
    }

    public T removeFront() {
        if (head == null) {
            return null;
        }
        T data = head.data;
        head = head.next;
        if (head == null) {
            tail = null;
        } else {
            head.prev = null;
        }
        size--;
        return data;
    }

    public T removeBack() {
        if (tail == null) {
            return null;
        }
        T data = tail.data;
        tail = tail.prev;
        if (tail == null) {
            head = null;
        } else {
            tail.next = null;
        }
        size--;
        return data;
    }
}

